import requests, json, time
API_KEY = '[REDACTED_GALAXY_API_KEY]'
BASE_URL = 'https://usegalaxy.org'
HISTORY_ID = 'bbd44e69cb8906b50fa42c2c23c64b9b'
headers = {'x-api-key': API_KEY}

# Download both outputs
r_animals = requests.get(f'{BASE_URL}/api/datasets/f9cad7b01a472135e93c5a5ae985281a/display', headers=headers)
r_fungi = requests.get(f'{BASE_URL}/api/datasets/f9cad7b01a4721359e8da10ed8c17b0a/display', headers=headers)

# Build combined tabular
lines = ['group\tpis_count']
for line in r_animals.text.strip().split('\n')[1:]:
    parts = line.split('\t')
    if len(parts) >= 2:
        lines.append('animals\t' + parts[1])
for line in r_fungi.text.strip().split('\n')[1:]:
    parts = line.split('\t')
    if len(parts) >= 2:
        lines.append('fungi\t' + parts[1])
combined = '\n'.join(lines)
print(f'Combined rows: {len(lines)-1}')

# Upload with inline data
r = requests.post(
    f'{BASE_URL}/api/tools',
    headers={**headers, 'Content-Type': 'application/json'},
    json={
        'history_id': HISTORY_ID,
        'tool_id': 'upload1',
        'inputs': {
            'files_0|type': 'upload_dataset',
            'files_0|name': 'pis_combined.tsv',
            'files_0|file_data': combined,
            'files_0|space_to_tab': 'false',
            'files_0|to_posix_lines': 'true',
            'file_type': 'tabular',
            'dbkey': '?',
        }
    }
)
result = r.json()
print('Upload submitted')

# Get job IDs
if 'jobs' in result:
    for job in result['jobs']:
        job_id = job['id']
        print('Job ID:', job_id)
        for i in range(300):
            time.sleep(1)
            r2 = requests.get(f'{BASE_URL}/api/jobs/{job_id}?full=true', headers=headers)
            jr = r2.json()
            state = jr.get('state')
            if state in ('ok', 'error', 'deleted'):
                print('Final state:', state)
                if state == 'ok' and 'outputs' in jr:
                    for out_name, out_info in jr['outputs'].items():
                        print('  Output:', out_name, '->', out_info.get('id'))
                break
            if i % 10 == 0:
                print('  State:', state, f'({i}s)')
elif 'outputs' in result:
    for out in result['outputs']:
        print('Direct output ID:', out['id'], out['name'], out['state'])
PYEOF

